def calculate_panel_efficiency(panel_data):
    # Validate input data
    if not isinstance(panel_data, dict) or not all(isinstance(values, list) and values for values in panel_data.values()):
        raise ValueError("Invalid input data. Panel data should be a dictionary with lists of efficiencies.")

    efficiencies = {}
    for panel, efficiency_values in panel_data.items():
        # Check for missing or invalid data
        if any(not isinstance(efficiency, (int, float)) or efficiency < 0 for efficiency in efficiency_values):
            raise ValueError(f"Invalid efficiency value(s) found for panel {panel}.")

        # Calculate average and standard deviation
        average_efficiency = statistics.mean(efficiency_values)
        std_deviation = statistics.stdev(efficiency_values)

        # Store results
        efficiencies[panel] = {"Average Efficiency": average_efficiency, "Standard Deviation": std_deviation}

    # Sort panels by average efficiency
    sorted_efficiencies = sorted(efficiencies.items(), key=lambda x: x[1]["Average Efficiency"], reverse=True)

    return sorted_efficiencies

